import{c as a,Q as t,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Lightweight LLM Agent Memory with Small Language Models","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.07798","title":"Lightweight LLM Agent Memory with Small Language Models","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2604.07798,"authors":["Jiaquan Zhang","Chaoning Zhang","Shuxu Chen","Zhenzhen Huang","Pengcheng Zheng","Zhicheng Wang","Ping Guo","Fan Mo","Sung-Ho Bae","Jie Zou","Jiwei Wei","Yang Yang"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2604.07798v1","pdf_path":"pdfs/2604.07798.pdf","published_date":"2026-04-10T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-10-lightweight-llm-agent-memory-small-models-2604-07798.md","filePath":"research/papers/2026-04-10-lightweight-llm-agent-memory-small-models-2604-07798.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-04-10-lightweight-llm-agent-memory-small-models-2604-07798.md"};function i(l,e,s,g,m,d){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="lightweight-llm-agent-memory-with-small-language-models" tabindex="-1">Lightweight LLM Agent Memory with Small Language Models <a class="header-anchor" href="#lightweight-llm-agent-memory-with-small-language-models" aria-label="Permalink to &quot;Lightweight LLM Agent Memory with Small Language Models&quot;">​</a></h1><p><strong>Authors</strong>: Jiaquan Zhang, Chaoning Zhang, Shuxu Chen, Zhenzhen Huang, Pengcheng Zheng, Zhicheng Wang, Ping Guo, Fan Mo, Sung-Ho Bae, Jie Zou, Jiwei Wei, Yang Yang <strong>Published</strong>: April 10, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.07798" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.07798</a> · <a href="https://arxiv.org/html/2604.07798v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2604.07798 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.07798" target="_blank" rel="noreferrer">research/papers/pdfs/2604.07798.pdf</a> (16 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Although LLM agents can leverage tools for complex tasks, they still need memory to maintain cross-turn consistency and accumulate reusable information in long-horizon interactions. However, retrieval-based external memory systems incur low online overhead but suffer from unstable accuracy due to limited query construction and candidate filtering. In contrast, many systems use repeated large-model calls for online memory operations, improving accuracy but accumulating latency over long interactions. We propose LightMem, a lightweight memory system for better agent memory driven by Small Language Models (SLMs). LightMem modularizes memory retrieval, writing, and long-term consolidation, and separates online processing from offline consolidation to enable efficient memory invocation under bounded compute. We organize memory into short-term memory (STM) for immediate conversational context, mid-term memory (MTM) for reusable interaction summaries, and long-term memory (LTM) for consolidated knowledge, and uses user identifiers to support independent retrieval and incremental maintenance in multi-user settings. Online, LightMem operates under a fixed retrieval budget and selects memories via a two-stage procedure: vector-based coarse retrieval followed by semantic consistency re-ranking. Offline, it abstracts reusable interaction evidence and incrementally integrates it into LTM. Experiments show consistent gains across model scales, with an average F1 improvement of about 2.5 over A-MEM on LoCoMo, while achieving higher efficiency and low median latency (83 ms for retrieval and 581 ms end-to-end).</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 LightMem：由 Small Language Models（SLM）驅動的輕量記憶系統，模組化 retrieval / writing / long-term consolidation，並分離 online 處理與 offline consolidation 以在有限算力下高效調用。</li><li>三層記憶組織：STM（即時對話脈絡）、MTM（可重用互動摘要）、LTM（整合後知識）；以 user identifier 支援多使用者獨立檢索與增量維護。</li><li>Online 在固定 retrieval budget 下以兩階段選取記憶：vector coarse retrieval + semantic consistency re-ranking；Offline 抽象互動證據並增量整合進 LTM。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>跨模型尺度一致增益：LoCoMo 上相較 A-MEM 平均 F1 提升約 +2.5。</li><li>高效率與低延遲：median 檢索 83 ms、端到端 581 ms。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未於 abstract 列明確 limitation；判斷弱點：SLM 抽取品質可能在高度專業領域退化；F1 +2.5 為單一 benchmark，跨域泛化未量化。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「online vs offline consolidation 分離」+「fixed retrieval budget」精準對應 context-management 的 token budget 與「右脈絡 &gt; 多脈絡」NLAH 原則。</li><li>用 SLM 做記憶 read/write 對應 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的 model-selection-grid：低風險抽取/檢索委派 Haiku 級模型，符合 <code>pilot</code>（tier=cost，原 <code>haiku-pilot</code>） 成本紀律。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li>「兩階段 coarse retrieval + re-rank」對應「判斷 vs 決定」：確定性 vector 召回（決定）+ LLM 語意 re-rank（判斷）的清晰分層。</li></ul>',16)])])}const u=a(o,[["render",i]]);export{c as __pageData,u as default};
